// 2. [T=1] Vault calls addObligation(1000). Escrow totalOwed becomes 1000.
// 3. [T=2] Vault transfers 1000 USDC to Escrow. Escrow balance becomes 1000.
// 4. [T=3] Vault calls payOut(user, 999) simulating a rounded-down redemption payout. Escrow totalOwed becomes 1, balance becomes 1.
// 5. [T=4] Vault attempts to reclaimTo(vault, 1) to recover the 1 USDC rounding excess.
// 6. [Assert] reclaimTo reverts because balance (1) < amount (1) + totalOwed (1). The 1 USDC is permanently locked in the escrow.

import "forge-std/Test.sol";
import "../src/core/RedeemEscrow.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract MockUSDC is ERC20 {
    constructor() ERC20("Mock USDC", "USDC") {}
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
    function decimals() public pure override returns (uint8) {
        return 6;
    }
}

contract MockACL {
    function checkRole(bytes32, address) external pure {}
    function hasRole(bytes32, address) external pure returns (bool) {
        return true;
    }
}

contract AuditAgentPoC is Test {
    RedeemEscrow public redeemEscrow;
    MockUSDC public usdc;
    MockACL public acl;
    address public user = address(0xBEEF);

    function setUp() public {
        usdc = new MockUSDC();
        acl = new MockACL();
        redeemEscrow = new RedeemEscrow();

        // Initialize RedeemEscrow with this contract as the vault
        redeemEscrow.initialize(address(usdc), address(this), address(acl));
    }

    function test_exploit() public {
        // Step 1: Vault records an obligation of 1000 USDC
        uint256 obligationAmount = 1000 * 1e6;
        redeemEscrow.addObligation(obligationAmount);
        console.log("Step 1: totalOwed =", redeemEscrow.totalOwed());

        // Step 2: Vault funds the escrow with 1000 USDC
        usdc.mint(address(redeemEscrow), obligationAmount);
        console.log("Step 2: escrow balance =", redeemEscrow.balance());

        // Step 3: Vault pays out 999 USDC to user (simulating rounding down in USDM->USDC conversion)
        uint256 payoutAmount = 999 * 1e6;
        redeemEscrow.payOut(user, payoutAmount);
        console.log("Step 3: totalOwed after payout =", redeemEscrow.totalOwed());
        console.log("Step 3: escrow balance after payout =", redeemEscrow.balance());

        // Step 4: Vault attempts to reclaim the 1 USDC excess
        uint256 excessAmount = 1 * 1e6;

        // The reclaimTo function checks: bal >= amount + totalOwed
        // Here: 1e6 >= 1e6 + 1e6 => False, so it will revert.
        // This proves the funds are permanently locked due to the desync.
        vm.expectRevert();
        redeemEscrow.reclaimTo(address(this), excessAmount);

        // Assert that the excess is still stuck in the escrow
        assertEq(usdc.balanceOf(address(redeemEscrow)), excessAmount, "Excess USDC is permanently locked in escrow");
    }
}

