// 5. [T=3 + cooldown] User claims unstake and receives exactly 1000 USDM (locked at old rate).
// 6. [Assert] Verify Escrow balance is exactly 1000 USDM (user's locked amount), while sUSDM holds 2000 USDM for the remaining staker. The 1000 USDM yield that should have accrued to the user was extracted by the remaining staker/vault.

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    USDM usdm;
    MonetrixConfig config;
    sUSDM susdm;
    sUSDMEscrow escrow;

    address governor = address(this);
    address user = address(0x1);
    address remainingStaker = address(0x2);

    function setUp() public {
        // Fix: Bypass OZ v5 _disableInitializers() in constructors by etching empty bytecode
        // This allows direct initialization of implementation contracts in the test environment.
        bytes memory emptyCode = hex"";

        acl = new MonetrixAccessController();
        vm.etch(address(acl), emptyCode);
        acl.initialize(governor);

        usdm = new USDM();
        vm.etch(address(usdm), emptyCode);
        usdm.initialize(address(acl));
        usdm.setVault(governor); // Allow test contract to mint USDM

        config = new MonetrixConfig();
        vm.etch(address(config), emptyCode);
        config.initialize(address(0), address(0), address(acl));
        config.setCooldowns(3 days, 3 days);
        config.setMaxYieldPerInjection(type(uint256).max);

        susdm = new sUSDM();
        vm.etch(address(susdm), emptyCode);
        susdm.initialize(address(usdm), address(config), address(acl));

        escrow = new sUSDMEscrow(address(usdm), address(susdm));
        susdm.setEscrow(address(escrow));
        susdm.setVault(governor); // Allow test contract to inject yield

        // Mint USDM to users
        usdm.mint(user, 1000 * 1e18);
        usdm.mint(remainingStaker, 1000 * 1e18);

        // Users approve and deposit
        vm.prank(user);
        usdm.approve(address(susdm), 1000 * 1e18);
        vm.prank(user);
        susdm.deposit(1000 * 1e18, user);

        vm.prank(remainingStaker);
        usdm.approve(address(susdm), 1000 * 1e18);
        vm.prank(remainingStaker);
        susdm.deposit(1000 * 1e18, remainingStaker);
